use crate::prelude::*;
use beet::prelude::*;

/// A document package's outline, `outline.json`: which documents exist, in
/// reading order, the `##` sections of each with what each holds, and the data
/// blocks they carry. It names no subject; a change to it is a change to every
/// workspace written against it, recorded in its history.
///
/// The outline is the one list of the documents, sections and blocks: the
/// evals restating it are generated by [`evals`](Self::evals) rather than
/// written as rows, and every anchor in the workspace is checked against its
/// sections.
#[derive(Debug, Clone, PartialEq, Reflect, Serialize, Deserialize)]
pub struct Outline {
	/// The source tag every generated eval cites, defined in the package's
	/// source table as this outline.
	pub source: SourceTag,
	/// The documents, in reading order.
	pub documents: Vec<DocumentSpec>,
	/// The data blocks the documents carry.
	pub blocks: Vec<BlockSpec>,
	/// Every change to the outline, oldest first.
	pub history: Vec<HistoryEntry>,
}

impl Outline {
	/// The outline's path at its package's root.
	pub const FILE: &str = "outline.json";

	/// The namespace of the generated evals, shared with the package's own
	/// checks on the shape of the set.
	pub const NAMESPACE: &str = "structure";

	/// The evals that restate the outline, in the `structure` namespace: for
	/// each document `<document>-present` and `<document>-sections`, for each
	/// block `<block>-block`, and over the set `frontmatter-complete` and
	/// `summaries-present`. Each is binary and checked, and cites
	/// [`source`](Self::source).
	pub fn evals(&self) -> Result<Vec<Eval>> {
		let names = self
			.documents
			.iter()
			.map(|document| document.name.clone())
			.collect::<Vec<_>>();
		let per_document = self.documents.iter().flat_map(|document| {
			let name = &document.name;
			[
				self.eval(
					&format!("{name}-present"),
					format!(
						"The {name} document exists, as `docs/{name}.md` or \
						 `docs/{name}/index.md`."
					),
					CheckRef::new("document", DocumentCheckParams {
						document: name.clone(),
					}),
				),
				self.eval(
					&format!("{name}-sections"),
					format!(
						"The {name} document carries exactly the sections the \
						 outline fixes for it, in order."
					),
					CheckRef::new("sections", SectionsCheckParams {
						document: name.clone(),
						headings: document
							.sections
							.iter()
							.map(|section| section.heading.clone())
							.collect(),
					}),
				),
			]
		});
		let per_block = self.blocks.iter().map(|block| {
			self.eval(
				&format!("{}-block", block.name),
				format!(
					"The `{}` block is defined once, under `{}`, with the \
					 columns the outline fixes.",
					block.name, block.lives_in
				),
				CheckRef::new("block", BlockCheckParams {
					name: block.name.clone(),
					section: block.lives_in.clone(),
					columns: block
						.columns
						.iter()
						.map(|column| column.to_string().into())
						.collect(),
				}),
			)
		});
		let over_the_set = [
			self.eval(
				"frontmatter-complete",
				"Every document carries `created`, `updated` and `authors` in \
				 its frontmatter."
					.into(),
				CheckRef::new("frontmatter", FrontmatterCheckParams {
					keys: DocumentSet::META_KEYS.map(SmolStr::new).to_vec(),
					documents: names.clone(),
				}),
			),
			self.eval(
				"summaries-present",
				"Every document opens with a summary paragraph between its \
				 title and its first section."
					.into(),
				CheckRef::new("summary", SummaryCheckParams {
					documents: names,
				}),
			),
		];
		per_document.chain(per_block).chain(over_the_set).collect()
	}

	fn eval(
		&self,
		slug: &str,
		statement: String,
		check: Result<CheckRef>,
	) -> Result<Eval> {
		Eval {
			id: EvalId::new(Self::NAMESPACE, slug)?,
			statement,
			levels: Levels::Binary {
				check: Some(check?),
			},
			sources: vec![self.source.clone()],
			anchor: None,
			note: None,
		}
		.xok()
	}
}

/// One document of a [`Outline`].
#[derive(Debug, Clone, PartialEq, Reflect, Serialize, Deserialize)]
pub struct DocumentSpec {
	/// The document's name and address, ie `market`.
	pub name: SmolStr,
	/// What the document is for and what its title and summary carry.
	pub summary: String,
	/// Its `##` sections, in order.
	pub sections: Vec<SectionSpec>,
}

/// One `##` section of a [`DocumentSpec`].
#[derive(Debug, Clone, PartialEq, Reflect, Serialize, Deserialize)]
pub struct SectionSpec {
	/// The heading as every document writes it, ie `Owner's finances`; its
	/// [`Address::slug`] is the section's address.
	pub heading: SmolStr,
	/// What the section holds, which is also where a grader looks for the evals
	/// anchored in it.
	pub holds: String,
}

/// One data block of a [`Outline`].
#[derive(Debug, Clone, PartialEq, Reflect, Serialize, Deserialize)]
pub struct BlockSpec {
	/// The block's name, ie `price-list`.
	pub name: SmolStr,
	/// The section it is defined under, ie `product#pricing`.
	pub lives_in: Address,
	/// Its columns, in order.
	pub columns: Vec<Column>,
}

/// One change to a [`Outline`].
#[derive(Debug, Clone, PartialEq, Reflect, Serialize, Deserialize)]
pub struct HistoryEntry {
	/// The day of the change.
	pub date: Date,
	/// What changed and why.
	pub change: String,
}

#[cfg(test)]
mod test {
	use crate::prelude::*;
	use beet::prelude::*;

	fn document(name: &str, headings: &[&str]) -> DocumentSpec {
		DocumentSpec {
			name: name.into(),
			summary: "A summary.".into(),
			sections: headings
				.iter()
				.map(|heading| SectionSpec {
					heading: SmolStr::new(heading),
					holds: "What it holds.".into(),
				})
				.collect(),
		}
	}

	/// The outline generates one eval per restated fact, each checked, its
	/// params the shape its check route reads.
	#[beet::test]
	fn generates_the_evals_restating_it() {
		let evals = Outline {
			source: SourceTag::parse("acme:outline").unwrap(),
			documents: vec![
				document("index", &["Mission"]),
				document("product", &["Idea", "Pricing"]),
			],
			blocks: vec![BlockSpec {
				name: "price-list".into(),
				lives_in: Address::parse("product#pricing").unwrap(),
				columns: vec![
					Column::parse("line").unwrap(),
					Column::parse("price_ex_gst:num").unwrap(),
				],
			}],
			history: Vec::new(),
		}
		.evals()
		.unwrap();
		evals
			.iter()
			.map(|eval| eval.id.as_str())
			.collect::<Vec<_>>()
			.xpect_eq(vec![
				"structure.index-present",
				"structure.index-sections",
				"structure.product-present",
				"structure.product-sections",
				"structure.price-list-block",
				"structure.frontmatter-complete",
				"structure.summaries-present",
			]);
		let params = |id: &str| {
			evals
				.iter()
				.find(|eval| eval.id.as_str() == id)
				.and_then(|eval| eval.levels.check())
				.unwrap()
				.params
				.clone()
		};
		params("structure.product-sections")
			.into_serde::<SectionsCheckParams>()
			.unwrap()
			.headings
			.xpect_eq(vec!["Idea".to_string(), "Pricing".into()]);
		params("structure.price-list-block")
			.into_serde::<BlockCheckParams>()
			.unwrap()
			.columns
			.xpect_eq(vec![SmolStr::new("line"), "price_ex_gst:num".into()]);
		params("structure.frontmatter-complete")
			.into_serde::<FrontmatterCheckParams>()
			.unwrap()
			.documents
			.xpect_eq(vec![SmolStr::new("index"), "product".into()]);
	}
}
